use mgbfs_runtime::generic_route::GenericRouteGeometry;
#[test] fn global128_geometry_has_no_u32_rank_mask(){let g=GenericRouteGeometry::new(&vec![1;128],(0..128).rev().collect(),16,1024).unwrap();assert_eq!(g.destination(0),(127,0));assert_eq!(g.destination(u64::MAX),(0,15));assert_eq!(g.bank_bytes,128*16*1024*32);}
#[test] fn weighted_non_power_two_boundaries_and_bad_maps(){let g=GenericRouteGeometry::new(&[1,2,1],vec![2,0,1],3,7).unwrap();assert_eq!(g.owner_cuts,vec![0,1<<30,3<<30,1u64<<32]);assert_eq!(g.destination(1u64<<62),(0,0));assert_eq!(g.destination(u64::MAX),(1,2));assert!(GenericRouteGeometry::new(&[1,1],vec![0,0],1,1).is_err());assert!(GenericRouteGeometry::new(&[0,1],vec![0,1],1,1).is_err());assert!(GenericRouteGeometry::new(&[1,u64::MAX],vec![0,1],1,1).is_err());}
